<!DOCTYPE html><html lang="en"><head>    <meta charset="UTF-8">    <meta name="viewport" content="width=device-width, initial-scale=1.0">    <title>Email Notification</title>    <style>        body {            font-family: 'Arial', sans-serif;            background-color: #f7f7f7;            padding: 20px;            margin: 0;        }        .email-container {            max-width: 600px;            margin: 0 auto;            background-color: #ffffff;            padding: 30px;            border-radius: 8px;            box-shadow: 0 4px 10px rgba(0,0,0,0.1);        }        .email-header {            text-align: center;            margin-bottom: 20px;        }        .email-header h1 {            font-size: 24px;            color: #333333;            margin: 0;        }        .email-body {            font-size: 16px;            color: #333333;            line-height: 1.6;        }        .footer {            font-size: 14px;            color: #999999;            text-align: center;            margin-top: 20px;        }        .footer a {            color: #007bff;            text-decoration: none;        }    </style></head><body><div class="email-container">    <div class="email-header">        <h1>{{ config('app.name') }}</h1>    </div>    <div class="email-body">        <p>{!! $maildata['message'] !!}</p>    </div>    <div class="footer">        <p>Best regards,</p>        <p>{{ config('app.name') }}</p>        <p><a href="{{ url('/') }}">{{ config('app.url') }}</a></p>    </div></div></body></html>